import{y as e,b as n,c as a,X as o}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const p=JSON.parse('{"title":"FastMCP Graceful Shutdown (G-OP-10)","description":"","frontmatter":{},"headers":[],"relativePath":"FASTMCP_GRACEFUL_SHUTDOWN.md","filePath":"FASTMCP_GRACEFUL_SHUTDOWN.md","lastUpdated":1771753292000}'),r={name:"FASTMCP_GRACEFUL_SHUTDOWN.md"};function i(s,t,d,l,c,u){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="fastmcp-graceful-shutdown-g-op-10" tabindex="-1">FastMCP Graceful Shutdown (G-OP-10) <a class="header-anchor" href="#fastmcp-graceful-shutdown-g-op-10" aria-label="Permalink to &quot;FastMCP Graceful Shutdown (G-OP-10)&quot;">​</a></h1><p>undefined<strong>Purpose:</strong> Design and document graceful shutdown for MCP server. undefined<strong>Date:</strong> 2026-02-14 undefined<strong>Scope:</strong> G-OP-10</p><hr><h2 id="_1-current-state" tabindex="-1">1. Current State <a class="header-anchor" href="#_1-current-state" aria-label="Permalink to &quot;1. Current State&quot;">​</a></h2><ul><li>undefined<strong>Lifespan:</strong> <code>thegent_lifespan</code> stops bundled proxy on teardown.</li><li>undefined<strong>Gap:</strong> No explicit drain of in-flight requests; no wait for active background runs (up to 30s).</li></ul><hr><h2 id="_2-design" tabindex="-1">2. Design <a class="header-anchor" href="#_2-design" aria-label="Permalink to &quot;2. Design&quot;">​</a></h2><h3 id="_2-1-shutdown-sequence" tabindex="-1">2.1 Shutdown Sequence <a class="header-anchor" href="#_2-1-shutdown-sequence" aria-label="Permalink to &quot;2.1 Shutdown Sequence&quot;">​</a></h3><ol><li>Receive SIGTERM/SIGINT</li><li>Stop accepting new connections (FastMCP/Starlette default)</li><li>undefined<strong>Optional:</strong> Wait up to <code>THGENT_SHUTDOWN_WAIT_S</code> for in-flight tool calls to complete</li><li>undefined<strong>Optional:</strong> Wait up to N seconds for active background runs (thegent_bg sessions) to finish</li><li>Terminate bundled proxy</li><li>Exit</li></ol><h3 id="_2-2-configuration" tabindex="-1">2.2 Configuration <a class="header-anchor" href="#_2-2-configuration" aria-label="Permalink to &quot;2.2 Configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Env</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>THGENT_SHUTDOWN_WAIT_S</td><td>0</td><td>Seconds to wait for in-flight requests before hard exit. 0 = no wait.</td></tr><tr><td>THGENT_SHUTDOWN_WAIT_ACTIVE_S</td><td>0</td><td>Seconds to poll for active background runs; wait until count=0 or timeout. 0 = no wait.</td></tr></tbody></table><h3 id="_2-3-active-run-tracking" tabindex="-1">2.3 Active Run Tracking <a class="header-anchor" href="#_2-3-active-run-tracking" aria-label="Permalink to &quot;2.3 Active Run Tracking&quot;">​</a></h3><p>Background runs (thegent_bg) spawn subprocesses. The server does not block on them.</p><ul><li>undefined<strong>THGENT_SHUTDOWN_WAIT_ACTIVE_S:</strong> When set, the lifespan teardown polls <code>ps_impl(all=True)</code> every 2s. If any session has <code>status == &quot;running&quot;</code>, it waits. Exits when no running sessions or timeout (max 120s).</li></ul><hr><h2 id="_3-implementation-phases" tabindex="-1">3. Implementation Phases <a class="header-anchor" href="#_3-implementation-phases" aria-label="Permalink to &quot;3. Implementation Phases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Deliverable</th><th>Status</th></tr></thead><tbody><tr><td>P1</td><td>Design doc (this)</td><td>Done</td></tr><tr><td>P2</td><td>THGENT_SHUTDOWN_WAIT_S in lifespan; asyncio.sleep before yield teardown</td><td>Done</td></tr><tr><td>P3</td><td>Optional: poll ps_impl for active runs; THGENT_SHUTDOWN_WAIT_ACTIVE_S</td><td>Done</td></tr></tbody></table><hr><h2 id="_4-references" tabindex="-1">4. References <a class="header-anchor" href="#_4-references" aria-label="Permalink to &quot;4. References&quot;">​</a></h2><ul><li><code>src/thegent/mcp_server.py</code> — thegent_lifespan</li><li><code>docs/FASTMCP_OPTIMIZATION_AUDIT.md</code> — G-OP-10</li></ul>',20)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
